import { randomBytes, randomInt, scryptSync, timingSafeEqual } from "node:crypto";

// ADR-045 phase C: credentials of the RandevuN calendar account. The password is generated by
// the app (never chosen by the user, never an Apple password) and stored only as an scrypt hash.

const HANDLE_ALPHABET = "abcdefghijkmnpqrstuvwxyz23456789"; // no 0/o/1/l: typed on a phone
const SCRYPT_N = 16384;
const KEY_LENGTH = 32;

function randomString(length: number): string {
  let out = "";
  for (let i = 0; i < length; i++) out += HANDLE_ALPHABET[randomInt(HANDLE_ALPHABET.length)];
  return out;
}

/** "<8 chars>.<tenant slug>": the slug routes Basic auth to the tenant without any lookup. */
export function generateUsername(slug: string): string {
  return `${randomString(8)}.${slug}`;
}

/** 4 groups of 4 (≈ 80 bits), easy to type into iPhone Settings. */
export function generatePassword(): string {
  return Array.from({ length: 4 }, () => randomString(4)).join("-");
}

export function hashPassword(password: string): string {
  const salt = randomBytes(16);
  const hash = scryptSync(password, salt, KEY_LENGTH, { N: SCRYPT_N });
  return `scrypt$${SCRYPT_N}$${salt.toString("base64url")}$${hash.toString("base64url")}`;
}

export function verifyPassword(password: string, stored: string): boolean {
  const [scheme, n, salt, hash] = stored.split("$");
  if (scheme !== "scrypt" || !n || !salt || !hash) return false;
  const expected = Buffer.from(hash, "base64url");
  try {
    const actual = scryptSync(password, Buffer.from(salt, "base64url"), expected.length, { N: Number(n) });
    return actual.length === expected.length && timingSafeEqual(actual, expected);
  } catch {
    return false;
  }
}

/** Username of a Basic Authorization header split into handle and tenant slug, or null. */
export function parseBasicAuth(header: string | null): { username: string; slug: string; password: string } | null {
  if (!header?.startsWith("Basic ")) return null;
  let decoded: string;
  try {
    decoded = Buffer.from(header.slice(6).trim(), "base64").toString("utf8");
  } catch {
    return null;
  }
  const colon = decoded.indexOf(":");
  if (colon < 0) return null;
  const username = decoded.slice(0, colon).trim().toLowerCase();
  const password = decoded.slice(colon + 1);
  const m = /^[a-z0-9]{8}\.([a-z0-9-]{1,120})$/.exec(username);
  if (!m || password.length === 0 || password.length > 200) return null;
  return { username, slug: m[1], password };
}
